def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in set(x for row in grid for x in row)
               if sum(all(x == v for x in row) for row in grid) > 0
               and sum(all(grid[r][c] == v for r in range(h)) for c in range(w)) > 0)

    def bands(n, is_sep):
        out = []
        start = 0
        for i in range(n):
            if is_sep(i):
                if i > start:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out

    rb = bands(h, lambda r: all(x == sep for x in grid[r]))
    cb = bands(w, lambda c: all(grid[r][c] == sep for r in range(h)))

    colors = {}
    for row in grid:
        for x in row:
            if x != sep:
                colors[x] = colors.get(x, 0) + 1
    bg = max(colors, key=colors.get)
    fg = min((x for x in colors if x != bg), key=lambda x: colors[x])

    result = []
    for r0, r1 in rb:
        row = []
        for c0, c1 in cb:
            n = sum(grid[r][c] == fg for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if n >= 2 else bg)
        result.append(row)
    return result
